// Some portions generated by Codex
package org.eclipse.rdf4j.query.explanation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Proxy;

import org.eclipse.rdf4j.query.GraphQuery;
import org.junit.jupiter.api.Test;

class ExplanationOptionsTest {
	@Test
	void restoresNestedOptionsOnFailure() {
		try (var outer = ExplanationOptions.values().activate()) {
			assertThrows(IllegalStateException.class, () -> {
				try (var inner = ExplanationOptions.serialized("application/sparql-results+json").activate()) {
					throw new IllegalStateException();
				}
			});
			assertEquals(ExplanationOptions.values(), ExplanationOptions.current());
		}
		assertEquals(ExplanationOptions.rows(), ExplanationOptions.current());
	}

	@Test
	void validatesExplicitConsumptionWithoutSilentlyChangingWork() {
		assertEquals(ExplanationOptions.rows(), ExplanationOptions.fromParameters(null, null));
		assertThrows(IllegalArgumentException.class, () -> ExplanationOptions.fromParameters("unknown", null));
		assertThrows(IllegalArgumentException.class, () -> ExplanationOptions.fromParameters("serialized", null));
		assertThrows(IllegalArgumentException.class,
				() -> ExplanationOptions.fromParameters("values", "application/sparql-results+json"));
		assertThrows(IllegalArgumentException.class,
				() -> ExplanationOptions.values().validate(Explanation.Level.Timed));
	}

	@Test
	void cannotSerializeGraphAlgebraAsTupleResults() {
		GraphQuery graph = (GraphQuery) Proxy.newProxyInstance(GraphQuery.class.getClassLoader(),
				new Class<?>[] { GraphQuery.class }, (proxy, method, arguments) -> {
					if (method.isDefault()) {
						return InvocationHandler.invokeDefault(proxy, method, arguments);
					}
					throw new AssertionError("The invalid workload must be rejected before evaluating the query");
				});
		assertThrows(IllegalArgumentException.class,
				() -> graph.explain(Explanation.Level.Telemetry,
						ExplanationOptions.serialized("application/sparql-results+json")));
		assertEquals(ExplanationOptions.rows(), ExplanationOptions.current());
	}
}
